const a = Math.abs(P.a) < 0.15 ? 0.15 : P.a;
const b = P.b, c = P.c;
const f = x => a * x * x + b * x + c;
const disc = b * b - 4 * a * c;
if (disc > 0) {
  const r1 = (-b - Math.sqrt(disc)) / (2 * a), r2 = (-b + Math.sqrt(disc)) / (2 * a);
  const lo = Math.min(r1, r2), hi = Math.max(r1, r2);
  if (a > 0) {
    // opens up: f<0 strictly BETWEEN the roots
    for (let x = lo; x <= hi; x += (hi - lo) / 60) {
      v.line(x, 0, x, f(x), { color: H.colors.warn, width: 2 });
    }
    H.text("solution of  ax² + bx + c < 0:   " + lo.toFixed(2) + " < x < " + hi.toFixed(2), 24, 74, { color: H.colors.warn, size: 13, weight: 600 });
  } else {
    // opens down: f<0 OUTSIDE the roots (x<lo or x>hi)
    for (let x = -8; x <= lo; x += (lo - (-8)) / 40 || 1) {
      v.line(x, 0, x, f(x), { color: H.colors.warn, width: 2 });
    }
    for (let x = hi; x <= 8; x += (8 - hi) / 40 || 1) {
      v.line(x, 0, x, f(x), { color: H.colors.warn, width: 2 });
    }
    H.text("solution of  ax² + bx + c < 0:   x < " + lo.toFixed(2) + "  or  x > " + hi.toFixed(2), 24, 74, { color: H.colors.warn, size: 13, weight: 600 });
  }
  v.dot(lo, 0, { r: 6, fill: H.colors.good });
  v.dot(hi, 0, { r: 6, fill: H.colors.good });
} else {
  // no real roots: sign is constant = sign(a)
  if (a < 0) {
    for (let x = -8; x <= 8; x += 16 / 80) {
      v.line(x, 0, x, f(x), { color: H.colors.warn, width: 2 });
    }
  }
  H.text(a > 0 ? "no real roots: ax²+bx+c < 0 has NO solution" : "no real roots: ax²+bx+c < 0 for ALL x", 24, 74, { color: H.colors.warn, size: 13, weight: 600 });
}
